3	/**
4	 * Invites one member; enforces the seat quota and the invite rate limit.
5	 *
6	 * Owner D. Pending invitations count against `seats` — otherwise an org on the
7	 * free plan could queue fifty invitations and blow past three seats the moment
8	 * they are accepted.
9	 *
10	 * Must call (do not reimplement): inviteMemberSchema, can, getPlanLimits,
11	 * consumeRateLimit, getActor, toActionResult
12	 */
13	
14	import {
15	  ForbiddenActionError,
16	  PlanLimitError,
17	  RateLimitedError,
18	} from "@/actions/_lib/action-errors";
19	import { PENDING_MEMBER_ID } from "@/actions/_lib/permission-resources";
20	import { withAction } from "@/actions/_lib/with-action";
21	import { getPlanLimits } from "@/config/plan-limits";
22	import { CACHE_PROFILES, orgTag, revalidateTagged } from "@/lib/cache";
23	import { can } from "@/lib/permissions";
24	import { consumeRateLimit } from "@/lib/rate-limit";
25	import { inviteMemberSchema, type InviteMemberInput } from "@/schemas/member";
26	import { inviteMember } from "@/server/services/invitation-service";
27	import { getOrganizationSummary } from "@/server/services/organization-service";
28	import type { ActionResult } from "@/types/api";
29	import type { Invitation } from "@/types/member";
30	
31	const INVITE_BUCKET = "member:invite";
32	
33	const run = withAction<typeof inviteMemberSchema, Invitation>(
34	  inviteMemberSchema,
35	  async (raw, actor) => {
36	    const input = raw as InviteMemberInput;
37	
38	    const allowed = can(actor, "member:invite", {
39	      kind: "member",
40	      orgId: input.orgId,
41	      memberId: PENDING_MEMBER_ID,
42	      targetUserId: actor.userId,
43	      targetRole: input.role,
44	    });
45	    if (!allowed) {
46	      throw new ForbiddenActionError("member:invite");
47	    }
48	
49	    const verdict = await consumeRateLimit(input.orgId, INVITE_BUCKET);
50	    if (!verdict.allowed) {
51	      throw new RateLimitedError(INVITE_BUCKET, verdict.resetAt);
52	    }
53	
54	    const summary = await getOrganizationSummary(actor, input.orgId);
55	    const limits = getPlanLimits(summary.organization.plan);
56	    if (summary.usage.seatsUsed + 1 > limits.seats) {
57	      throw new PlanLimitError("seats", limits.seats, summary.usage.seatsUsed);
58	    }
59	
60	    const invitation = await inviteMember(actor, input);
61	    revalidateTagged([orgTag(input.orgId)], CACHE_PROFILES.minutes);
62	    return invitation;
63	  },
64	  { revalidate: ["members", "invitations"], cacheProfile: "minutes" },
65	);
66	
67	export async function inviteMemberAction(raw: unknown): Promise<ActionResult<Invitation>> {
68	  return run(raw);
69	}
